import os
import torch


class Config:
    # --------------------------------------------------------------------------
    # Directory & File Paths
    # --------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_4"
    SUBMISSION_DIR = "./submission"

    # Metadata Files (Generated by the provided script)
    TRAIN_META_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_META_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_META_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Raw Data Files
    TRAIN_DATA_PATH = os.path.join(INPUT_DIR, "train.csv")
    TEST_DATA_PATH = os.path.join(INPUT_DIR, "test.csv")
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Output Files
    # We use .npz for caching processed data to avoid pickle
    PROCESSED_DATA_PATH = os.path.join(WORKING_DIR, "processed_data.npz")
    MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # --------------------------------------------------------------------------
    # Data Configuration
    # --------------------------------------------------------------------------
    # Numerical features: f_00..f_26 and f_28..f_30 (30 features total)
    NUM_COLS = [f"f_{i:02d}" for i in range(31) if i != 27]
    CAT_COL = "f_27"
    TARGET_COL = "target"
    ID_COL = "id"

    # Sequence configuration for f_27 decomposition
    SEQ_LEN = 10
    # Vocabulary size estimate (A-Z + padding/unknown).
    # We will compute exact size during processing, but this is a safe init.
    VOCAB_SIZE = 30

    # --------------------------------------------------------------------------
    # Model Architecture: Gated Wide MLP (GLU-MLP)
    # --------------------------------------------------------------------------
    EMBED_DIM = 32
    # Wide layers with decreasing size
    HIDDEN_DIMS = [1024, 512, 256]
    DROPOUT = 0.25

    # --------------------------------------------------------------------------
    # Training Hyperparameters
    # --------------------------------------------------------------------------
    SEED = 42
    BATCH_SIZE = 2048
    EPOCHS = 50
    LEARNING_RATE = 1e-3
    # High weight decay as specified for Gated MLP
    WEIGHT_DECAY = 1e-2
    PATIENCE = 10  # Early stopping patience

    # Compute
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    @staticmethod
    def setup():
        """Creates necessary output directories."""
        os.makedirs(Config.WORKING_DIR, exist_ok=True)
        os.makedirs(Config.SUBMISSION_DIR, exist_ok=True)
